%% Get volumes for semantic matching task – Controls – MNI space
epi_mainfolder = dir([data_path 'sub-control' sub{i} '/fmriprep/sub-control' sub{i} '/ses-' num2str(s) '/func']);
curr_epi_subfolder = epi_mainfolder.folder;
nifti_files = dir([curr_epi_subfolder '/sub-control' sub{i} '_ses-' num2str(s) '_task-semanticmatching_run-' run{x} '_space-MNI152NLin6Asym_desc-preproc_bold.nii']);
func_images_path = [nifti_files.folder '/' nifti_files.name];
    func_vols = spm_vol(func_images_path);
    Vols = {};
    for iVol = 1:numel(func_vols)
        Vols{iVol} = [func_images_path ',' num2str(iVol)];
    end
    Vols = Vols';

clear matlabbatch

elseif s == 2 | s == 3
    if strcmp('control', group)
        if strcmp('standard', space)
            %% Display which participant is currently processed
            X = ['This is semantic matching in standard space. This is control participant ' sub{i} ' and session ' num2str(s)];
                disp(X);

            %% Get smoothed epis for each run
            % Run-1
            epi_folder = dir([data_path 'sub-control' sub{i} '/fmriprep/sub-control' sub{i} '/ses-' num2str(s) '/func/']);
            curr_epi_folder = epi_folder.folder;
            nifti_files = dir([curr_epi_folder '/ssub-control' sub{i} '_ses-' num2str(s) '_task-semanticmatching_run-1_space-MNI152NLin6Asym_desc-preproc_bold.nii']);
            func_images_path = [nifti_files.folder '/' nifti_files.name];
                func_vols = spm_vol(func_images_path);
                Vols_1 = {};
                for iVol = 1:numel(func_vols)
                    Vols_1{iVol} = [func_images_path ',' num2str(iVol)];
                end
                Vols_1 = Vols_1';

            % Run-2    
            epi_folder = dir([data_path 'sub-control' sub{i} '/fmriprep/sub-control' sub{i} '/ses-' num2str(s) '/func']);
            curr_epi_folder = epi_folder.folder;
            nifti_files = dir([curr_epi_folder '/ssub-control' sub{i} '_ses-' num2str(s) '_task-semanticmatching_run-2_space-MNI152NLin6Asym_desc-preproc_bold.nii']);

%                 %% Get GM mask
%                 GM_folder = dir([data_path 'sub-control' sub{i} '/fmriprep/sub-control' sub{i} '/ses-1/anat/sub-control' sub{i} '_space-MNI152NLin6Asym_label-GM_thr02.nii']);                            
%                 GM_mask = [GM_folder.folder '/' GM_folder.name];

                %% Define output directory
                output_dir = [stats_path 'sub-control' sub{i} '/ses-' num2str(s) '/1st_level_semanticmatching_allTrialsEqualDurations'];
                if ~exist(output_dir)
                    mkdir(output_dir)
                end

% FPM-WPM
curr_con = 'con_0008';
dest = [group_folder 'FPM-WPM_act_sham_conImages'];
if ~exist(dest)
    mkdir(dest)
end
con_img_sham = [stats_path 'sub-control' sub{i} '/ses-2/1st_level_semanticmatching_allTrialsEqualDurations/' curr_con '.nii'];
copyfile(con_img_sham, [dest filesep curr_con '_sub-control' sub{i} '_sham.nii']);
con_img_active = [stats_path 'sub-control' sub{i} '/ses-3/1st_level_semanticmatching_allTrialsEqualDurations/' curr_con '.nii'];
copyfile(con_img_active, [dest filesep curr_con '_sub-control' sub{i} '_active.nii']);

% WPM-FPM

X = ['Processing control participant ' sub{i}];
disp(X);

%% Get active con-image
con_active_path = dir([stats_folder currDir filesep '*_sub-control' sub{i} '_active.nii']);
con_active = [con_active_path.folder filesep con_active_path.name];

%% Get sham con-image
con_sham_path = dir([stats_folder currDir filesep '*_sub-control' sub{i} '_sham.nii']);
con_sham = [con_sham_path.folder filesep con_sham_path.name];

%% Define output directory
output_dir = [group_folder 'Control_group_Active-Sham_OneSample_ttest/' currDir];
output_dir = strrep(output_dir, 'conImages', 'masked');
if ~exist(output_dir)
    mkdir(output_dir)
end
output_name = ['sub-control' sub{i} '_active-sham'];

%% Run batch
clear matlabbatch
matlabbatch{1}.spm.util.imcalc.input = {con_active
                                        con_sham};
matlabbatch{1}.spm.util.imcalc.output = output_name;
matlabbatch{1}.spm.util.imcalc.outdir = {output_dir};
matlabbatch{1}.spm.util.imcalc.expression = 'i1-i2';
matlabbatch{1}.spm.util.imcalc.var = struct('name', {}, 'value', {});
matlabbatch{1}.spm.util.imcalc.options.dmtx = 0;
matlabbatch{1}.spm.util.imcalc.options.mask = 0;
matlabbatch{1}.spm.util.imcalc.options.interp = -7;

%% FPM_WPM
con_path = [data_path 'FPM-WPM_act_sham_masked'];

con_images = dir([con_path '/sub-*.nii']);
        Vols = {};
        for j = 1:numel(con_images)
            Vols(j,:) = cellstr([con_path '/' con_images(j).name]);
        end

    clear matlabbatch
    matlabbatch{1}.spm.stats.factorial_design.dir = {con_path};
    matlabbatch{1}.spm.stats.factorial_design.des.t1.scans = Vols;

    %
    matlabbatch{1}.spm.stats.factorial_design.cov = struct('c', {}, 'cname', {}, 'iCFI', {}, 'iCC', {});
    matlabbatch{1}.spm.stats.factorial_design.multi_cov = struct('files', {}, 'iCFI', {}, 'iCC', {});
    matlabbatch{1}.spm.stats.factorial_design.masking.tm.tm_none = 1;
    matlabbatch{1}.spm.stats.factorial_design.masking.im = 1;
    matlabbatch{1}.spm.stats.factorial_design.masking.em = {GM_mask};
    matlabbatch{1}.spm.stats.factorial_design.globalc.g_omit = 1;
    matlabbatch{1}.spm.stats.factorial_design.globalm.gmsca.gmsca_no = 1;
    matlabbatch{1}.spm.stats.factorial_design.globalm.glonorm = 1;

    % Navigate to output directory, specify and estimate GLM
    spm_jobman('run', matlabbatch)
    cd(con_path);

    load SPM;
    spm_spm(SPM);

    clear matlabbatch
    spmmat = dir([con_path '/SPM.mat']);
    matlabbatch{1}.spm.stats.con.spmmat = {[spmmat.folder '/' spmmat.name]};
    matlabbatch{1}.spm.stats.con.consess{1}.tcon.name = 'active>sham';
    matlabbatch{1}.spm.stats.con.consess{1}.tcon.weights = 1;
    matlabbatch{1}.spm.stats.con.consess{1}.tcon.sessrep = 'none';
    matlabbatch{1}.spm.stats.con.consess{2}.tcon.name = 'sham>active';
    matlabbatch{1}.spm.stats.con.consess{2}.tcon.weights = -1;
    matlabbatch{1}.spm.stats.con.consess{2}.tcon.sessrep = 'none';
    matlabbatch{1}.spm.stats.con.consess{3}.fcon.name = 'all';
    matlabbatch{1}.spm.stats.con.consess{3}.fcon.weights = 1;
    matlabbatch{1}.spm.stats.con.consess{3}.fcon.sessrep = 'none';
